insert into public.content (key, value) values ('events', $json$[{"id":"openframe","kind":"Фестиваль","title":"Open Frame Astana 2027","who":"Фестиваль короткого метра для молодых кинематографистов от 15 до 21 года.","deadline":"2027-03-01","dtext":"Заявки до 1 марта 2027","note":"Онлайн-отбор, итоги 15 марта 2027. Финал очно в Астане 4 апреля 2027.","src":"98mag.kz","url":"https://www.98mag.kz/likbez/kinofestival-open-frame-astana-2027-obyavil-o-starte-open-kolla/"},{"id":"visualis","kind":"Фестиваль","title":"Визуалис","who":"Международный фестиваль: короткие фильмы до 40 минут, полнометражные от 60 минут.","deadline":"2026-10-27","dtext":"Ближайший срок 27 октября 2026, дальше сроки до 10 сентября 2027","note":"Взнос за короткометражный фильм — 650 рублей. Заявки принимаются только через платформу.","src":"FestAgent","url":"https://festagent.com/ru/festivals/visualis"},{"id":"baiqonyr","kind":"Фестиваль","title":"Baiqonyr Film Festival","who":"Международный фестиваль в Казахстане: конкурс национального короткометражного кино, дебютное игровое кино, питчинг сценариев.","deadline":"2026-07-01","dtext":"Приём 2026 года закрылся 1 июля","note":"Фестиваль 2026 прошёл 19–25 сентября. Следите за открытием набора на следующий год.","src":"PRO Production","url":"https://prp.kz/2026/03/02/xi-baiqonyr-film-festival-otkryl-priyom-zayavok-dedlayn-1-iyulya/"},{"id":"kinoproba","kind":"Фестиваль","title":"Кинопроба","who":"Фестиваль-практикум киношкол: игровые, документальные и анимационные фильмы до 30 минут.","deadline":"2026-09-01","dtext":"Приём 2026 года закрылся 1 сентября","note":"Подача бесплатная. Следите за следующим набором.","src":"FestAgent","url":"https://festagent.com/ru/festivals/kinoproba"},{"id":"comeondoc","kind":"Фестиваль","title":"COME ON DOC","who":"Международный фестиваль дебютного короткого документального кино (3–39 минут), принимает студенческие работы.","deadline":"2026-06-27","dtext":"Стандартный срок 2026 года — 27 июня","note":"Следите за открытием набора на следующий год.","src":"FestAgent","url":"https://festagent.com/ru/festivals/comeondoc"},{"id":"gosts","kind":"Поддержка","title":"Господдержка национальных фильмов","who":"Государственный центр поддержки национального кино финансирует отобранные кинопроекты: игровые, документальные, анимацию.","deadline":null,"dtext":"Конкурс 2026 прошёл","state":"Следите за новым набором","note":"В 2026 году конкурс стартовал 1 марта: подано 323 заявки, отобрано 18 проектов. Правила отбора — в приказе Минкультуры.","src":"Әділет","url":"https://adilet.zan.kz/rus/docs/V1900018405"},{"id":"debutshort","kind":"Поддержка","title":"Конкурс дебютных короткометражных фильмов","who":"Минкультуры вместе с «Казахфильмом» отбирает проекты начинающих авторов для запуска в производство.","deadline":null,"dtext":"Итоги 2026 подведены 17 марта","state":"Следите за новым набором","note":"В 2026 году рекомендованы два проекта: «Дом» Тимура Хосчанова и «Күн қайдан шығады?» Айши Салимгереевой.","src":"Kazpravda.kz","url":"https://kazpravda.kz/n/itogi-konkursa-debyutnyh-korotkometrazhnyh-filmov-podveli-v-kazahstane/"},{"id":"kinohub","kind":"Поддержка","title":"Командный конкурс сценариев KinoHub.kz","who":"Конкурс сценариев коротких фильмов для команд: без ИИ, только совместная работа.","deadline":"2026-02-28","dtext":"Приём 2026 года закрылся 28 февраля","note":"Следите за конкурсом 2027 года.","src":"PRO Production","url":"https://prp.kz/2026/02/19/million-na-korotkiy-metr-v-kazahstane-zapustili-konkurs-stsenariev/"}]$json$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();

insert into public.content (key, value) values ('articles', $json$[{"cat":"Кино КЗ","date":"6 октября 2026","title":"В Астане прошёл первый Astana AI Film Festival","sum":"С 1 по 3 октября в столице показывали фильмы, сделанные с помощью искусственного интеллекта. На конкурс пришло 8 067 заявок из 125 стран. Гран-при получил латвийский автор Николай Шестак, а казахстанец Мырзахан Жумахан отмечен за лучшего персонажа в комедии «Это была просто шутка».","src":"Euronews","url":"https://www.euronews.com/2026/10/06/latvian-filmmaker-wins-400000-grand-prix-at-kazakhstans-ai-film-festival"},{"cat":"Кино КЗ","date":"1 августа 2026","title":"Казахстанский дебют «Мұғалім» отобран в Сан-Себастьян","sum":"Фильм Аяны Нурдиновой попал в конкурс новых режиссёров 74-го Международного кинофестиваля в Сан-Себастьяне. Это первый казахстанский фильм женщины-режиссёра в конкурсе этого фестиваля.","src":"The Astana Times","url":"https://astanatimes.com/2026/08/kazakh-cinema-expands-international-festival-presence-with-san-sebastian-selection/"},{"cat":"Кино КЗ","date":"2026","title":"Что Казахстан выдвинул на «Оскар»","sum":"По списку казахстанских заявок на премию «Оскар» за лучший международный фильм, в этом сезоне страну представляет «Әбіл» режиссёра Елзата Ескендира. Результат отбора пока не объявлен.","src":"Wikipedia","url":"https://en.wikipedia.org/wiki/List_of_Kazakhstani_submissions_for_the_Academy_Award_for_Best_International_Feature_Film"},{"cat":"Кино КЗ","date":"весна 2026","title":"Казахстанские премьеры весны: от драмы до «Тамерлана»","sum":"Youth.kz собрал заявленные на весну картины: «МАМА» Айбека Нигмета, «Черный двор в кино» Данияра Болотбекова, «Ерекше» Ернара Нургалиева, «Мошенники» Олжаса Нурбая и международный проект «Тамерлан» (США, Казахстан, Узбекистан).","src":"Youth.kz","url":"https://youth.kz/article/kazahstanskie-filmy-i-serialy-kotorye-vyjdut-vesnoj-2026-goda-k1cYRk66qO6fCofZjgVj"},{"cat":"Мир кино","date":"12 сентября 2026","title":"Венеция-2026: «Золотой лев» у датской драмы «Woman Unknown»","sum":"Главный приз 83-го Венецианского фестиваля получила Мэй эль-Тухи, а Кубок Вольпи за лучшую женскую роль — Матильда Арсель. «Серебряный лев» (Гран-при жюри) достался «Possible Love» Ли Чхан-дона, а за режиссуру награждён Илья Хржановский («DAU»).","src":"Euronews","url":"https://www.euronews.com/culture/2026/09/12/venice-film-festival-2026-woman-unknown-of-may-el-toukhy-wins-the-golden-lion"},{"cat":"Мир кино","date":"сентябрь 2026","title":"Рекорд Венеции: 25 минут аплодисментов","sum":"Поздно добавленный в программу фильм «Naza» с Джоном Малковичем и Сэмом Рокуэллом получил самую долгую овацию в истории фестиваля и специальный приз жюри.","src":"Euronews","url":"https://www.euronews.com/culture/2026/09/12/venice-film-festival-2026-woman-unknown-of-may-el-toukhy-wins-the-golden-lion"},{"cat":"Школа","date":"для студентов","title":"Как студенту сэкономить на аренде техники","tool":["rentals","Открыть ренталы и скидки"],"body":["Планируйте съёмки кучно: арендовать на три смены подряд часто выгоднее, чем брать технику три раза по одной смене.","Сравните минимум три рентала и спросите про пакетную цену. Покажите студенческий билет и сразу уточните залог — иногда его можно снизить.","Берите только то, что есть в шот-листе и светосхеме. Лишняя «на всякий случай» линза или прибор — это деньги и лишний вес на площадке.","При выдаче проверьте комплектацию и сфотографируйте состояние техники. Запас аккумуляторов и карт памяти обычно стоит дёшево, а простой съёмочной группы — дорого."]},{"cat":"Школа","date":"для операторов","title":"Светосхема за 10 минут: три точки света","tool":["lights","Нарисовать светосхему"],"body":["Начните с трёх приборов. Ключевой даёт основную форму лицу, заполняющий смягчает тени, контровой отделяет героя от фона.","Решите, с какой стороны ключ: рядом с камерой свет мягче и «ровнее», с боковой стороны — контрастнее и драматичнее.","Чем крупнее источник относительно героя и чем ближе он стоит, тем мягче тень. Дальний маленький прибор даёт жёсткую тень.","Запишите схему: мощность, температуру и насадку каждого прибора. Так гаффер соберёт свет без вопросов."]},{"cat":"Школа","date":"для режиссёров","title":"Шот-лист: зачем он нужен и как составить","tool":["shots","Открыть шот-лист"],"body":["Шот-лист — это список кадров по сценам. Для каждого кадра записывают размер, ракурс, движение камеры и коротко — что происходит.","Он экономит время на площадке: оператор заранее знает, какие объективы и крепления нужны, а вы — сколько кадров реально успеть за смену.","Начните со сцен, которые нельзя перенести, и отметьте «обязательные» кадры. Остальное снимайте, если останется время.","После съёмки отмечайте снятое галочкой: в конце дня сразу видно, что осталось."]},{"cat":"Школа","date":"для операторов","title":"Правило 180° и выдержка","tool":["calc","Открыть калькуляторы"],"body":["Угол затвора 180° означает, что выдержка равна половине длительности кадра. При 24 кадрах в секунду это 1/48 секунды.","Такая выдержка даёт привычное «киношное» размытие движения. Короче выдержка — резче, «рубленее» движение; длиннее — смазаннее.","Если на улице слишком светло, не прикрывайте диафрагму до упора и не меняйте выдержку, а поставьте ND-фильтр — он убирает свет, не меняя картинку."]},{"cat":"Школа","date":"для режиссёров","title":"Экспликация за один вечер","tool":["explic","Открыть экспликацию"],"body":["Экспликация — это ответ на вопрос «каким будет мой фильм». Начните с одного предложения: кто герой, чего он хочет и что ему мешает.","Дальше коротко опишите тему, тон, визуальный язык и работу с актёрами. Добавьте два-три референса: кадры или фильмы, на которые вы хотите быть похожими.","Хорошая экспликация умещается на одну страницу и понятна человеку, который не читал сценарий."]}]$json$::jsonb)
  on conflict (key) do update set value = excluded.value, updated_at = now();

